<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $uid=journeys_require_auth(); if($uid===null)exit; $d=journeys_input(); if(!journeys_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $jid=(int)($d['journey_id']??0); $type=(string)($d['item_type']??''); $source=(int)($d['source_id']??0); $title=trim((string)($d['title']??'')); $desc=trim((string)($d['description']??'')); $date=trim((string)($d['item_date']??'')); $j=$jid>0?journeys_find($db,$jid):null; if(!$j||!journeys_can_view($db,$j,$uid)){ApiResponse::notFound('Journey not found.');exit;} if(!journeys_can_contribute($db,$j,$uid)){ApiResponse::forbidden('Not allowed to contribute.');exit;} if(!in_array($type,['memory','milestone','event'],true)){ApiResponse::validation(['item_type'=>'Invalid item type.']);exit;} if($date!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){ApiResponse::validation(['item_date'=>'Invalid date.']);exit;} if($type==='memory'){ $s=$db->prepare('SELECT id,user_id,title,description,memory_date,privacy_level,folder_id FROM memories WHERE id=:id AND status=\'active\' LIMIT 1'); $s->execute(['id'=>$source]); $m=$s->fetch(PDO::FETCH_ASSOC); if(!$m||((int)$m['user_id']!==$uid&&!PrivacyService::canView($db,'memory',(int)$m['id'],(int)$m['user_id'],$uid,(string)$m['privacy_level'],isset($m['folder_id'])?(int)$m['folder_id']:null))){ApiResponse::forbidden('Memory not accessible.');exit;} $title=$title?:$m['title']; $desc=$desc?:($m['description']??''); $date=$date?:($m['memory_date']??''); }
 if($type==='milestone'){ $s=$db->prepare('SELECT id,user_id,title,description,milestone_date,privacy_level FROM milestones WHERE id=:id AND status=\'active\' LIMIT 1'); $s->execute(['id'=>$source]); $m=$s->fetch(PDO::FETCH_ASSOC); if(!$m||((int)$m['user_id']!==$uid&&!PrivacyService::canView($db,'milestone',(int)$m['id'],(int)$m['user_id'],$uid,(string)$m['privacy_level']))){ApiResponse::forbidden('Milestone not accessible.');exit;} $title=$title?:$m['title']; $desc=$desc?:($m['description']??''); $date=$date?:($m['milestone_date']??''); }
 if($type==='event'&&$title===''){ApiResponse::validation(['title'=>'Title required.']);exit;} if($title===''||mb_strlen($title)>255||mb_strlen($desc)>JOURNEY_ITEM_NOTE_MAX){ApiResponse::validation(['item'=>'Valid item required.']);exit;} $status=journeys_can_manage($db,$j,$uid)?'approved':'pending'; $ins=$db->prepare('INSERT INTO journey_items (journey_id,contributor_id,item_type,source_id,title,description,item_date,status) VALUES (:j,:u,:type,:source,:title,:description,:date,:status)'); $ins->execute(['j'=>$jid,'u'=>$uid,'type'=>$type,'source'=>$type==='event'?null:$source,'title'=>$title,'description'=>$desc?:null,'date'=>$date?:null,'status'=>$status]); if(!journeys_can_manage($db,$j,$uid)) NotificationService::createOnce($db,(int)$j['owner_id'],$uid,NotificationService::TYPE_JOURNEY_INVITATION,'journey',$jid,'submitted a journey contribution.'); ApiResponse::success(['item_id'=>(int)$db->lastInsertId(),'status'=>$status],'Contribution submitted.',201); }catch(Throwable $e){Logger::error('Journey add item failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to add journey item.');}
?>
